return await page.evaluate(async () => {
  const beforeFavicon = document.querySelector('link[rel="icon"]')?.href;
  (document.querySelector('#canvas-rce-shell [data-appearance="dark"]'))?.click();
  const dark = {
    themeColor: document.querySelector('meta[name="theme-color"]')?.content,
    rootBackground: getComputedStyle(document.documentElement).backgroundColor,
    colorScheme: document.documentElement.style.colorScheme,
  };
  (document.querySelector('#canvas-rce-shell [data-color="red"]'))?.click();
  const afterFavicon = document.querySelector('link[rel="icon"]')?.href;
  return { beforeFavicon, afterFavicon, faviconChanged: beforeFavicon !== afterFavicon, dark };
});

